/**
 * Phase 1 lands the full domain model (tickets, messages, kb_articles,
 * ai_calls, outbound_messages) here.
 *
 * Auth tables live in auth-schema.ts and are generated by
 * `@better-auth/cli generate` — never edit them by hand. They replace the
 * earlier hand-rolled `users` table: Better Auth owns user/session/account/
 * verification, and passwords live in `account.password`, not on the user.
 *
 * Re-exported rather than imported piecemeal so drizzle.config.ts can keep
 * pointing at this one file and `drizzle({ client, schema })` sees everything.
 */
export * from "./auth-schema.ts";
